# Contract-driven Count20 staging/admission. No lock, process, compiler, or native action.
param(
 [Parameter(Mandatory=$true)][string]$Count1SourcesRoot,
 [Parameter(Mandatory=$true)][string]$Count20LifecycleRoot,
 [Parameter(Mandatory=$true)][string]$OutputRoot,
 [Parameter(Mandatory=$true)][string]$OriginalCount1CertificatePath,
 [Parameter(Mandatory=$true)][string]$OriginalCount1CertificateHash,
 [Parameter(Mandatory=$true)][int64]$OriginalCount1CertificateBytes
)
Set-StrictMode -Version Latest;$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'assert-count20-count1-certificate.ps1')
function Item([string]$Path,[int64]$Limit=67108864){$i=Get-Item -LiteralPath $Path -Force -ErrorAction Stop;if($i.PSIsContainer -or $i.LinkType -or (($i.Attributes-band [IO.FileAttributes]::ReparsePoint)-ne 0) -or $i.Length -gt $Limit){throw ('Bounded regular non-reparse file required: '+$Path)};return $i}
function Hash([string]$Path,[int64]$Limit=67108864){$i=Item $Path $Limit;$s=$null;$h=$null;$n=0L;try{$s=[IO.File]::Open($i.FullName,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read);$h=[Security.Cryptography.SHA256]::Create();$b=New-Object byte[] 1048576;while(($r=$s.Read($b,0,$b.Length))-gt 0){$h.TransformBlock($b,0,$r,$b,0)|Out-Null;$n+=$r;if($n -gt $Limit){throw 'Hash limit exceeded'}};$h.TransformFinalBlock($b,0,0)|Out-Null;if($n -ne [int64]$i.Length){throw 'Input changed while hashing'};return ([BitConverter]::ToString($h.Hash)-replace '-','').ToLowerInvariant()}finally{if($h){$h.Dispose()};if($s){$s.Dispose()}}}
function Json([string]$Path){return [IO.File]::ReadAllText((Item $Path 4194304).FullName,[Text.UTF8Encoding]::new($false))|ConvertFrom-Json}
function Rel([string]$Path){if([string]::IsNullOrWhiteSpace($Path)-or [IO.Path]::IsPathRooted($Path)-or $Path -match '(^|[\\/])\.\.([\\/]|$)'-or $Path -match '(^|[\\/]):'-or $Path.StartsWith('/')-or $Path.StartsWith('\')){throw ('Unsafe relative source path: '+$Path)};return (($Path-replace '\\','/').TrimStart('./'))}
function Inside([string]$Root,[string]$Relative){$r=([IO.Path]::GetFullPath($Root)).TrimEnd([IO.Path]::DirectorySeparatorChar,[IO.Path]::AltDirectorySeparatorChar);$p=[IO.Path]::GetFullPath((Join-Path $r $Relative));if(-not $p.StartsWith($r+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)){throw 'Source path escaped root'};return $p}
function CopyExact([string]$Source,[string]$Destination){$src=Item $Source;$destParent=Split-Path -Parent $Destination;New-Item -ItemType Directory -Force -Path $destParent|Out-Null;if(Test-Path -LiteralPath $Destination){throw ('Refusing overwrite: '+$Destination)};$input=$null;$output=$null;$bytes=0L;try{$input=[IO.File]::Open($src.FullName,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::Read);$output=[IO.File]::Open($Destination,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write,[IO.FileShare]::None);$buffer=New-Object byte[] 1048576;while(($read=$input.Read($buffer,0,$buffer.Length))-gt 0){$output.Write($buffer,0,$read);$bytes+=$read;if($bytes -gt 67108864){throw 'Copy limit exceeded'}};$output.Flush();if($bytes -ne [int64]$src.Length){throw 'Source changed during copy'}}finally{if($output){$output.Dispose()};if($input){$input.Dispose()}};if((Hash $Destination)-cne (Hash $Source)){throw ('Copied source hash mismatch: '+$Source)};return [ordered]@{bytes=$bytes;sha256=(Hash $Destination)}}
function MapRows($Map){$rows=@();if($Map.source){$rows+=@($Map.source)};$rows+=@($Map.overlaySources);$rows+=@($Map.sourceControls);if($rows.Count -eq 0){throw 'Count20 lifecycle source map empty'};return $rows}

$count1=[IO.Path]::GetFullPath($Count1SourcesRoot);$lifecycle=[IO.Path]::GetFullPath($Count20LifecycleRoot);$out=[IO.Path]::GetFullPath($OutputRoot)
if(Test-Path -LiteralPath $out){throw 'Fresh Count20 output root required'}
$certificate=Assert-Count20OriginalCount1Certificate $OriginalCount1CertificatePath $OriginalCount1CertificateHash $OriginalCount1CertificateBytes
$mapPath=Join-Path $lifecycle 'source-map.json';$map=Json $mapPath
$mapPin=CopyExact $mapPath (Join-Path (Join-Path $out 'lifecycle') 'source-map.json')
$stageRows=@();$overlayOut=Join-Path $out 'lifecycle';foreach($row in (MapRows $map)){$name=[IO.Path]::GetFileName([string]$row.path);if([string]::IsNullOrWhiteSpace($name)-or ([IO.Path]::GetDirectoryName([string]$row.path)-replace '\\','/') -notmatch 'count20-lifecycle-v1$'){throw 'Count20 source map row outside lifecycle packet'};$source=Join-Path $lifecycle $name;$stagedName=if($name -ceq 'capture-rectangle-count20-v1.ps1'){'capture-rectangle-count20-source-v1.ps1'}elseif($name -ceq 'uia-worker-invoke-v2.ps1'){'uia-worker-invoke-v2-source-v1.ps1'}else{$name};$dest=Join-Path $overlayOut $stagedName;$pin=CopyExact $source $dest;$expected=(([string]$row.sha256)-replace '^sha256:','').ToLowerInvariant();if($pin.bytes-ne [int64]$row.bytes-or $pin.sha256-ne $expected){throw ('Count20 lifecycle pin mismatch: '+$name)};$stageRows+=@([ordered]@{path=('lifecycle/'+$stagedName);bytes=$pin.bytes;sha256=$pin.sha256;role=$row.role})}
$count1Producer=Join-Path $count1 'producer';$count1Worker=Join-Path $count1Producer 'dependencies/uia-worker';$contractSource=Join-Path $count1Worker 'worker-contract.json';$contract=Json $contractSource;$integrationSource=Join-Path $count1Producer 'integration-bindings.json';$integration=Json $integrationSource;if($null -eq $integration.files){throw 'Count1 integration binding files missing'}
$producerOut=Join-Path $out 'producer';$workerOut=Join-Path $producerOut 'dependencies/uia-worker';$bindingRows=@($integration.files);$seen=@{};$workerRows=@();foreach($row in $bindingRows){$relative=Rel ([string]$row.path);if($seen.ContainsKey($relative)){throw ('Duplicate integration row: '+$relative)};$seen[$relative]=$true;$source=Inside $count1Producer $relative;$dest=Join-Path $producerOut $relative;$pin=CopyExact $source $dest;$expected=(([string]$row.sha256)-replace '^sha256:','').ToLowerInvariant();if($pin.bytes-ne [int64]$row.bytes-or $pin.sha256-ne $expected){throw ('Count1 integration pin mismatch: '+$relative)};$workerRows+=@([ordered]@{path=$relative;bytes=$pin.bytes;sha256=$pin.sha256})}
$integrationOut=Join-Path $producerOut 'integration-bindings.json';$integrationPin=CopyExact $integrationSource $integrationOut
$contractOut=Join-Path $workerOut 'worker-contract.json';$contractItemOut=Item $contractOut;$contractPin=[ordered]@{bytes=[int64]$contractItemOut.Length;sha256=(Hash $contractOut)}
$mtaSource=Join-Path $count1Worker 'invoke-worker-mta.ps1';$mtaInvokerPin=CopyExact $mtaSource (Join-Path $overlayOut 'uia-worker-invoke-v2.ps1');$stageRows+=@([ordered]@{path='lifecycle/uia-worker-invoke-v2.ps1';bytes=$mtaInvokerPin.bytes;sha256=$mtaInvokerPin.sha256;role='active Count20 MTA UIA invoker overlay'})
$mtaCaptureSource=Join-Path $PSScriptRoot 'capture-rectangle-count20-mta-v1.ps1';$mtaCapturePin=CopyExact $mtaCaptureSource (Join-Path $overlayOut 'capture-rectangle-count20-v1.ps1');$stageRows+=@([ordered]@{path='lifecycle/capture-rectangle-count20-v1.ps1';bytes=$mtaCapturePin.bytes;sha256=$mtaCapturePin.sha256;role='active Count20 capture bound to MTA invoker'})
$certificateHelperSource=Join-Path $PSScriptRoot 'assert-count20-count1-certificate.ps1';$certificateHelperPin=CopyExact $certificateHelperSource (Join-Path $overlayOut 'assert-count20-count1-certificate.ps1');$stageRows+=@([ordered]@{path='lifecycle/assert-count20-count1-certificate.ps1';bytes=$certificateHelperPin.bytes;sha256=$certificateHelperPin.sha256;role='Count1 prerequisite production guard'})
$closureHelper=Join-Path $PSScriptRoot '..\uia-source-closure-admission-v1\assert-uia-source-closure.ps1';$closureOut=Join-Path (Join-Path $out 'closure') 'assert-uia-source-closure.ps1';$closurePin=CopyExact $closureHelper $closureOut;. $closureOut
$mta=@($contract.sourceBindings|Where-Object{[string]$_.path -ceq 'invoke-worker-mta.ps1'});if($mta.Count-ne 1){throw 'Worker contract omits invoke-worker-mta.ps1'}
$admission=Assert-FactoryUiaSourceClosure -ProducerRoot $producerOut -WorkerSourceRoot $workerOut -WorkerContractPath $contractOut -IntegrationBindingsPath $integrationOut -IntegrationBindingsBytes $integrationPin.bytes -IntegrationBindingsHash $integrationPin.sha256 -SourceBindings @($contract.sourceBindings) -RequireMtaInvoker
$certificateRef=[ordered]@{path=[IO.Path]::GetFullPath($OriginalCount1CertificatePath);bytes=[int64](Item $OriginalCount1CertificatePath).Length;sha256=(Hash $OriginalCount1CertificatePath)}
$result=[ordered]@{kind='factory-rectangle-count20-mta-admission-v1';status='source-admitted-pending-count20-metadata-and-native';count=20;count1Certificate=$certificateRef;workerContract=[ordered]@{path='producer/dependencies/uia-worker/worker-contract.json';bytes=$contractPin.bytes;sha256=$contractPin.sha256;sourceCount=@($contract.sourceBindings).Count;mtaInvoker=$mta[0]};activeOverlay=[ordered]@{capturePath='lifecycle/capture-rectangle-count20-v1.ps1';captureBytes=$mtaCapturePin.bytes;captureSha256=$mtaCapturePin.sha256;invokerPath='lifecycle/uia-worker-invoke-v2.ps1';invokerBytes=$mtaInvokerPin.bytes;invokerSha256=$mtaInvokerPin.sha256;certificateGuardPath='lifecycle/assert-count20-count1-certificate.ps1';certificateGuardBytes=$certificateHelperPin.bytes;certificateGuardSha256=$certificateHelperPin.sha256;workerApartment='MTA'};integrationBindings=[ordered]@{path='producer/integration-bindings.json';bytes=$integrationPin.bytes;sha256=$integrationPin.sha256;rowCount=$bindingRows.Count};closure=$admission;lifecycleSources=$stageRows;nativeActions=0;compilerActions=0;remoteActions=0;lockActions=0}
$resultPath=Join-Path $out 'count20-mta-admission.json';$result|ConvertTo-Json -Depth 24|Set-Content -LiteralPath $resultPath -Encoding UTF8
Write-Output ($resultPath)
